<?php
namespace App\Models; use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class AnalysisBatch extends Model {use HasUuids;protected $guarded=[];protected function casts():array{return ['summary'=>'array','error'=>'array','period_start'=>'date','period_end'=>'date','started_at'=>'datetime','finished_at'=>'datetime'];}public function company(){return $this->belongsTo(Company::class);}public function catalogVersion(){return $this->belongsTo(FiscalCatalogVersion::class,'catalog_version_id');}public function sourceFiles(){return $this->hasMany(SourceFile::class);}public function documents(){return $this->hasMany(FiscalDocument::class);}public function findings(){return $this->hasMany(Finding::class);}public function reports(){return $this->hasMany(ReportArtifact::class);}}
